import { createContext, useState, useEffect } from 'react';
import axios from 'axios';

export const AuthContext = createContext();

export const AuthContextProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [token, setToken] = useState(sessionStorage.getItem('token') || null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    console.log('AuthContext: Initializing authentication');
    console.log('AuthContext: Stored token=', sessionStorage.getItem('token') || 'null');
    console.log('AuthContext: Stored user=', sessionStorage.getItem('user') || 'null');

    const storedToken = sessionStorage.getItem('token');
    if (!storedToken) {
      console.log('AuthContext: No token found, setting loading to false');
      setCurrentUser(null);
      setLoading(false);
      return;
    }

    console.log('AuthContext: Verifying token:', storedToken.substring(0, 20) + '...');
    axios
      .get('http://localhost:5000/api/users/me', {
        headers: { Authorization: `Bearer ${storedToken}` },
      })
      .then((res) => {
        console.log('AuthContext: Token verification response=', {
          status: res.status,
          data: JSON.stringify(res.data, null, 2),
          headers: JSON.stringify(res.headers, null, 2),
        });
        if (!res.data || !res.data._id) {
          console.log('AuthContext: Invalid or empty user data from /api/users/me');
          setError('Invalid user data. Please log in again.');
          setCurrentUser(null);
          setToken(null);
          sessionStorage.removeItem('user');
          sessionStorage.removeItem('token');
        } else {
          console.log('AuthContext: Setting currentUser=', {
            _id: res.data._id,
            username: res.data.username,
            name: res.data.name,
            email: res.data.email,
            friends: res.data.friends?.length || 0,
          });
          setCurrentUser(res.data);
          setToken(storedToken);
          sessionStorage.setItem('user', JSON.stringify(res.data));
        }
      })
      .catch((err) => {
        console.error('AuthContext: Token verification failed:', err.message);
        console.error('AuthContext: Error details:', {
          status: err.response?.status,
          data: JSON.stringify(err.response?.data, null, 2),
          headers: JSON.stringify(err.response?.headers, null, 2),
        });
        setCurrentUser(null);
        setToken(null);
        sessionStorage.removeItem('user');
        sessionStorage.removeItem('token');
        setError('Session expired or invalid token. Please log in again.');
      })
      .finally(() => {
        console.log('AuthContext: Token verification complete, loading=', false);
        console.log('AuthContext: currentUser=', currentUser ? JSON.stringify(currentUser, null, 2) : 'null');
        console.log('AuthContext: error=', error);
      });
  }, []);

  const login = async (username, password) => {
    try {
      setError(null);
      setLoading(true);
      console.log('AuthContext: Sending login request:', { username });
      const res = await axios.post('http://localhost:5000/api/auth/login', {
        username,
        password,
      });
      console.log('AuthContext: Login response=', {
        status: res.status,
        data: JSON.stringify(res.data, null, 2),
        headers: JSON.stringify(res.headers, null, 2),
      });
      const { user, token } = res.data;
      if (!user || !user._id || !token) {
        console.log('AuthContext: Invalid login response, missing user._id or token');
        throw new Error('Invalid login response from server.');
      }
      console.log('AuthContext: Setting currentUser after login=', {
        _id: user._id,
        username: user.username,
        name: user.name,
        email: user.email,
        friends: user.friends?.length || 0,
      });
      setCurrentUser(user);
      setToken(token);
      sessionStorage.setItem('user', JSON.stringify(user));
      sessionStorage.setItem('token', token);
      return true;
    } catch (err) {
      const message = err.response?.data?.message || 'Login failed';
      console.error('AuthContext: Login error:', {
        message: err.message,
        response: JSON.stringify(err.response?.data, null, 2),
        status: err.response?.status,
      });
      setError(message);
      setCurrentUser(null);
      setToken(null);
      sessionStorage.removeItem('user');
      sessionStorage.removeItem('token');
      throw new Error(message);
    } finally {
      console.log('AuthContext: Login attempt complete, loading=', false);
      setLoading(false);
    }
  };

  const logout = () => {
    console.log('AuthContext: Logging out');
    setCurrentUser(null);
    setToken(null);
    setError(null);
    sessionStorage.removeItem('user');
    sessionStorage.removeItem('token');
    setLoading(false);
  };

  return (
    <AuthContext.Provider
      value={{ currentUser, setCurrentUser, token, login, logout, error, loading }}
    >
      {children}
    </AuthContext.Provider>
  );
};
